def sort(items):
    if len(items) <= 1:
        return items
    mid = len(items) // 2
    left = sort(items[:mid])
    right = sort(items[mid:])
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i])
            i += 1
        else:
            merged.append(right[j])
            j += 1
    merged.extend(left[i:])
    merged.extend(right[j:])
    return merged
return sort(arr)

