def sort_range(low, high):
    while low < high:
        mid = (low + high) // 2
        arr[mid], arr[high] = arr[high], arr[mid]
        pivot = arr[high]
        boundary = low
        for j in range(low, high):
            if arr[j] < pivot:
                arr[boundary], arr[j] = arr[j], arr[boundary]
                boundary += 1
        arr[boundary], arr[high] = arr[high], arr[boundary]
        if boundary - low < high - boundary:
            sort_range(low, boundary - 1)
            low = boundary + 1
        else:
            sort_range(boundary + 1, high)
            high = boundary - 1
sort_range(0, len(arr) - 1)
return arr

